<template>
  <component :is="tag" class="exhibition-spoken-text" :class="{ 'is-speaking': active }">
    <template v-for="(segment,index) in segments" :key="index"><span v-if="segment.isWordLike" class="exhibition-spoken-word" :class="{ 'is-current': active && segment.wordIndex === wordIndex, 'is-heard': active && segment.wordIndex < wordIndex }">{{segment.text}}</span><template v-else>{{segment.text}}</template></template>
  </component>
</template>

<script>
import { exhibitionSpeechSegments } from '../../utils/exhibitionSpokenText';
export default {
  name:'ExhibitionSpokenText',
  props:{text:{type:String,default:''},language:{type:String,default:''},tag:{type:String,default:'p'},active:Boolean,follow:Boolean,wordIndex:{type:Number,default:-1}},
  computed:{segments(){return exhibitionSpeechSegments(this.text,this.language);}},
  watch: { wordIndex() { this.$nextTick(this.keepWordVisible); }, active() { this.$nextTick(this.keepWordVisible); } },
  methods: {
    keepWordVisible() {
      if (!this.active || !this.follow || this.wordIndex < 0) return;
      const word = this.$el.querySelector('.is-current'), panel = this.$el.closest('.exhibition-story-prose');
      if (!word || !panel) return;
      const bounds = panel.getBoundingClientRect(), current = word.getBoundingClientRect();
      if (current.top >= bounds.top + 12 && current.bottom <= bounds.bottom - 16) return;
      panel.scrollTo({ top: panel.scrollTop + current.top - bounds.top - Math.min(60, bounds.height * .2), behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
    },
  },
};
</script>
